logger = logging.getLogger(__name__)

_NUM_SIPS = 24
# Persistent-style grid caps (also keep grid.x within the GCU400 hardware
# limit, P19: grid.x <= 65535, regardless of tensor size).
_GRID_CAP = _NUM_SIPS * 2
_GRID_CAP_WIDE = _NUM_SIPS * 4
# int32 offset safe domain for the flat kernel: the masked tail block
# evaluates block_id * BLOCK + arange for masked lanes too, reaching
# num_blocks * BLOCK - 1; keep n <= 2^31 - 2^17 (BLOCK <= 131072).
_INT32_SAFE_LIMIT = (1 << 31) - (1 << 17)
_FLAT_DTYPES = (torch.float16, torch.bfloat16, torch.float32)
# Element budget per program iteration in the stream arms, expressed in
# 4-byte units (256 KB tiles): the DSM/program limit is ~896 KB, and the
# two half-row tiles of the PAIRS arm double-buffer within it.
_TILE_BUDGET_4B = 65536
_PAIRS_BUDGET_4B = 32768
# XOR-column stores need >= 1 KB contiguous runs (H' * 4 bytes) to keep the
# de-vectorized store path at full bandwidth; below that use the PAIRS arm.
_XORSTORE_MIN_HALF = 256


@libentry()
@triton.jit(do_not_specialize=["n_elements", "N", "HALF"])
def fft_ifftshift_lastdim_kernel(
    in_ptr,
    out_ptr,
    n_elements,
    N,
    HALF,
    LOG_HALF: tl.constexpr,  # HALF == 1 << LOG_HALF in the FLAT arm (else 0)
    W: tl.constexpr,  # FLAT: chunk width; PAIRS/XORSTORE: half-row width (== HALF)
    P: tl.constexpr,  # PAIRS/XORSTORE: whole rows per iteration; FLAT/ELEMENT: 1
    MODE: tl.constexpr,  # 0=FLAT, 1=PAIRS, 2=ELEMENT, 3=XORSTORE
    EVEN: tl.constexpr,  # no tail masks (checked on host per MODE)
):
    # Fast path: contiguous tensor, single shift along the last dim.
    # Semantics: out[e] = in[(e mod N + HALF) mod N]  (HALF = N // 2).
    #
    # FLAT (huge last dim, HALF >= chunk): each aligned chunk stays inside one
    # half, so src = chunk ^ HALF (scalar XOR base) -> one provably contiguous
    # copy per iteration (flat-copy family, memory-roofline form).
    # PAIRS (small HALF): each iteration swaps the halves of P whole rows via
    # two affine [P, HALF] tiles (row stride N) -> vectorized fast axis and
    # two independent loads per iteration.
    # XORSTORE (large HALF): sequential [P, N] full-row loads, stores at
    # XOR-swapped columns (out[r, c ^ HALF] = in[r, c]); reads stay perfectly
    # coalesced while the stores land in two >= 1 KB contiguous runs per row.
    # ELEMENT: general per-element fallback (non-power-of-two last dim).
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    if MODE == 0:
        ar = tl.arange(0, W)
        HALF_C: tl.constexpr = 1 << LOG_HALF
        num_blocks = (n_elements + W - 1) // W
        for block_id in tl.range(pid, num_blocks, num_pids):
            d0 = block_id * W
            src = d0 ^ HALF_C
            if EVEN:
                val = tl.load(in_ptr + src + ar)
                tl.store(out_ptr + d0 + ar, val)
            else:
                mask = d0 + ar < n_elements
                val = tl.load(in_ptr + src + ar, mask=mask)
                tl.store(out_ptr + d0 + ar, val, mask=mask)
    elif MODE == 1:
        ar_p = tl.arange(0, P)
        ar_w = tl.arange(0, W)
        group_bytes = N * P  # elements per iteration
        num_groups = (n_elements + group_bytes - 1) // group_bytes
        for g in tl.range(pid, num_groups, num_pids):
            rows = g * group_bytes + ar_p * N  # [P] row bases
            if EVEN:
                val_right = tl.load(in_ptr + rows[:, None] + HALF + ar_w[None, :])
                val_left = tl.load(in_ptr + rows[:, None] + ar_w[None, :])
                tl.store(out_ptr + rows[:, None] + ar_w[None, :], val_right)
                tl.store(out_ptr + rows[:, None] + HALF + ar_w[None, :], val_left)
            else:
                offs_l = rows[:, None] + ar_w[None, :]
                offs_r = offs_l + HALF
                mask = offs_l < n_elements
                val_right = tl.load(in_ptr + offs_r, mask=mask)
                val_left = tl.load(in_ptr + offs_l, mask=mask)
                tl.store(out_ptr + offs_l, val_right, mask=mask)
                tl.store(out_ptr + offs_r, val_left, mask=mask)
    elif MODE == 3:
        ar_p = tl.arange(0, P)
        ar_n = tl.arange(0, 2 * W)
        NC: tl.constexpr = 2 * W
        group = NC * P
        num_groups = (n_elements + group - 1) // group
        for g in tl.range(pid, num_groups, num_pids):
            rows = g * group + ar_p * NC  # [P] row bases
            if EVEN:
                full = tl.load(in_ptr + rows[:, None] + ar_n[None, :])
                tl.store(out_ptr + rows[:, None] + (ar_n[None, :] ^ W), full)
            else:
                mask = rows[:, None] + ar_n[None, :] < n_elements
                full = tl.load(in_ptr + rows[:, None] + ar_n[None, :], mask=mask)
                tl.store(out_ptr + rows[:, None] + (ar_n[None, :] ^ W), full, mask=mask)
    else:
        ar = tl.arange(0, W)
        num_blocks = (n_elements + W - 1) // W
        for block_id in tl.range(pid, num_blocks, num_pids):
            e = block_id * W + ar
            col = e % N
            src = tl.where(col >= (N - HALF), e - (N - HALF), e + HALF)
            if EVEN:
                val = tl.load(in_ptr + src)
                tl.store(out_ptr + e, val)
            else:
                mask = e < n_elements
                val = tl.load(in_ptr + src, mask=mask)
                tl.store(out_ptr + e, val, mask=mask)


@libentry()
@triton.jit(do_not_specialize=["n_elements"])
def fft_ifftshift_kernel(
    in_ptr_u8,  # pointer to input tensor as bytes
    out_ptr_u8,  # pointer to output tensor as bytes
    sizes_ptr,  # int64[NDIMS]
    in_strides_ptr,  # int64[NDIMS], in elements
    out_strides_ptr,  # int64[NDIMS], in elements
    adds_ptr,  # int64[NDIMS], per-dim add = floor(size/2) if shifted else 0
    n_elements,  # total number of elements
    ELEMENT_SIZE: tl.constexpr,  # number of bytes per element
    NDIMS: tl.constexpr,  # number of dimensions
    BLOCK_SIZE: tl.constexpr,  # tile size
):
    # General path: arbitrary dims / strides / dtypes via byte-wise gather.
    pid = tl.program_id(axis=0)
    num_pids = tl.num_programs(axis=0)
    arange = tl.arange(0, BLOCK_SIZE)
    n_total = n_elements.to(tl.int64)
    num_blocks = (n_total + BLOCK_SIZE - 1) // BLOCK_SIZE
    for block_id in tl.range(pid, num_blocks, num_pids):
        offs = block_id * BLOCK_SIZE + arange
        mask = offs < n_total
        offs64 = offs.to(tl.int64)

        # Compute multi-dimensional indices from linear index (row-major)
        tmp = offs64
        in_off_elems = tl.zeros([BLOCK_SIZE], dtype=tl.int64)
        out_off_elems = tl.zeros([BLOCK_SIZE], dtype=tl.int64)

        # Iterate from last dim to first to compute indices
        for d in range(NDIMS - 1, -1, -1):
            size_d = tl.load(sizes_ptr + d)  # scalar int64
            idx_d = tmp % size_d
            tmp = tmp // size_d

            add_d = tl.load(adds_ptr + d)  # scalar int64
            idx_in_d = idx_d + add_d
            # modulo to wrap within size_d
            idx_in_d = idx_in_d - (idx_in_d // size_d) * size_d

            in_stride_d = tl.load(in_strides_ptr + d)
            out_stride_d = tl.load(out_strides_ptr + d)

            in_off_elems += idx_in_d * in_stride_d
            out_off_elems += idx_d * out_stride_d

        in_byte_base = in_off_elems * ELEMENT_SIZE
        out_byte_base = out_off_elems * ELEMENT_SIZE

        # Copy ELEMENT_SIZE bytes per element
        for b in range(ELEMENT_SIZE):
            src_addr = in_ptr_u8 + in_byte_base + b
            dst_addr = out_ptr_u8 + out_byte_base + b
            val = tl.load(src_addr, mask=mask, other=0)
            tl.store(dst_addr, val, mask=mask)


def _normalize_dims(dim, ndim):
    if dim is None:
        return list(range(ndim))
    if isinstance(dim, int):
        dims_list = [dim]
    else:
        dims_list = list(dim)
    # normalize negative dims
    dims_list = [(d + ndim) % ndim for d in dims_list]
    # remove duplicates while preserving order
    seen = set()
    unique = []
    for d in dims_list:
        if d not in seen:
            unique.append(d)
            seen.add(d)
    return unique


def _launch_with_retry(launch):
    # The external llvm converter intermittently fails on cold compiles
    # (shared-node flake); retrying the launch recompiles and succeeds
    # (abs.py / neg.py / square.py precedents).
    for attempt in range(3):
        try:
            launch()
            return
        except Exception as exc:
            if attempt == 2:
                raise
            logger.warning(
                "fft_ifftshift kernel launch failed (attempt %d): %s",
                attempt + 1,
                exc,
            )


def _launch_general(x, out, adds_list):
    device = x.device
    # Metadata dtype: int32 inside the i32 safe domain (sizes/strides/adds all
    # < 2^31). With the int64 runtime env disabled torch_gcu silently degrades
    # int64 device tensors (storage replaced, dtype kept) which corrupts the
    # kernel-side loads; explicit int32 metadata is env-independent. Int64 is
    # kept for the (rare) oversized layouts.
    meta_values = list(x.shape) + list(x.stride()) + list(out.stride()) + adds_list
    if max(meta_values, default=0) < (1 << 31):
        meta_dtype = torch.int32
    else:
        meta_dtype = torch.int64
    sizes = torch.tensor(list(x.shape), device=device, dtype=meta_dtype)
    in_strides = torch.tensor(list(x.stride()), device=device, dtype=meta_dtype)
    out_strides = torch.tensor(list(out.stride()), device=device, dtype=meta_dtype)
    adds = torch.tensor(adds_list, device=device, dtype=meta_dtype)

    n = x.numel()
    # 0-dim tensors cannot be viewed as uint8 directly (dim-0 view cannot
    # change element size); reshape(1) is a storage-sharing view.
    x_u8 = x.reshape(1).view(torch.uint8) if x.ndim == 0 else x.view(torch.uint8)
    out_u8 = (
        out.reshape(1).view(torch.uint8) if out.ndim == 0 else out.view(torch.uint8)
    )

    block = 1024
    grid_size = min(triton.cdiv(max(n, 1), block), _GRID_CAP)
    element_size = x.element_size()
    ndims = x.ndim

    def _launch():
        with torch_device_fn.device(device):
            fft_ifftshift_kernel[(grid_size,)](
                x_u8,
                out_u8,
                sizes,
                in_strides,
                out_strides,
                adds,
                n,
                ELEMENT_SIZE=element_size,
                NDIMS=ndims,
                BLOCK_SIZE=block,
            )

    _launch_with_retry(_launch)


def fft_ifftshift(self, dim=None):
    logger.debug("GEMS_ENFLAME FFT_IFFTSHIFT")

    x = self
    ndim = x.ndim
    n = x.numel()

    if ndim == 0:
        # 0-dim: aten raises; FlagGems semantics = an independent copy of the
        # single element. Copied by our own kernel (no aten clone on the host
        # path).
        out = torch.empty_like(x)
        _launch_general(x, out, [])
        return out

    dims_list = _normalize_dims(dim, ndim)

    if n == 0:
        # Empty tensors: shape-preserving, no data to move.
        return torch.empty_like(x)

    last_dim = x.shape[-1]
    if (
        x.is_contiguous()
        and len(dims_list) == 1
        and dims_list[0] == ndim - 1
        and x.dtype in _FLAT_DTYPES
        and n < _INT32_SAFE_LIMIT
    ):
        out = torch.empty_like(x)
        # Power-of-two last dim (>= 4): halves are aligned 2^k segments and
        # the whole op is the flat half-swap out[e] = in[e ^ HALF].
        pow2 = last_dim >= 4 and (last_dim & (last_dim - 1)) == 0
        if pow2:
            # 16-bit dtypes run through an fp32 view (2 elements packed):
            # 4-byte accesses keep the de-vectorized XOR-column store path at
            # full bandwidth (2-byte accesses halve it).
            if x.dtype == torch.float32:
                xv, outv = x, out
            else:
                xv = x.view(torch.float32)
                outv = out.view(torch.float32)
            nv = xv.numel()
            last_dim_v = xv.shape[-1]
            half_v = last_dim_v // 2
            log_half = half_v.bit_length() - 1
            rows_total = nv // last_dim_v
            if half_v >= _TILE_BUDGET_4B:
                # FLAT: one contiguous chunk per iteration, scalar XOR base.
                mode, width, prows = 0, _TILE_BUDGET_4B, 1
                group = width
                grid_cap, num_warps, num_stages = _GRID_CAP, 4, 2
            elif half_v >= _XORSTORE_MIN_HALF:
                # XORSTORE: sequential full-row loads, swapped-column stores.
                mode = 3
                width = half_v
                prows = min(
                    max(_TILE_BUDGET_4B // (2 * half_v), 1),
                    max(triton.next_power_of_2(rows_total), 1),
                )
                group = last_dim_v * prows
                grid_cap, num_warps, num_stages = _GRID_CAP_WIDE, 8, 2
            else:
                # PAIRS: two affine half-row tiles per iteration.
                mode = 1
                width = half_v
                prows = min(
                    max(_PAIRS_BUDGET_4B // half_v, 1),
                    max(triton.next_power_of_2(rows_total), 1),
                )
                group = last_dim_v * prows
                grid_cap, num_warps, num_stages = _GRID_CAP, 8, 2
            even = nv % group == 0
            grid_size = min(triton.cdiv(nv, group), grid_cap)

            def _launch():
                with torch_device_fn.device(x.device):
                    fft_ifftshift_lastdim_kernel[(grid_size,)](
                        xv,
                        outv,
                        nv,
                        last_dim_v,
                        half_v,
                        LOG_HALF=log_half,
                        W=width,
                        P=prows,
                        MODE=mode,
                        EVEN=even,
                        num_warps=num_warps,
                        num_stages=num_stages,
                    )

            _launch_with_retry(_launch)
            return out

        # Non-power-of-two last dim: per-element fallback (test-sized inputs).
        half = last_dim // 2
        width = min(max(triton.next_power_of_2(n), 64), 65536)
        even = n % width == 0
        grid_size = min(triton.cdiv(n, width), _GRID_CAP)

        def _launch():
            with torch_device_fn.device(x.device):
                fft_ifftshift_lastdim_kernel[(grid_size,)](
                    x,
                    out,
                    n,
                    last_dim,
                    half,
                    LOG_HALF=0,
                    W=width,
                    P=1,
                    MODE=2,
                    EVEN=even,
                    num_warps=4,
                )

        _launch_with_retry(_launch)
        return out

    # General path: multi-dim shift / non-contiguous / other dtypes /
    # very large tensors.
    out = torch.empty_like(x)
    dims_set = set(dims_list)
    adds = [(x.shape[d] // 2) if d in dims_set else 0 for d in range(ndim)]
    _launch_general(x, out, adds)
    return out
